import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.hasNextInt() ? in.nextInt() : 0;
        long sum = 0;
        for (int i = 0; i < n; i++) {
            long x = in.nextLong();
            if (x % 2 == 0) sum += x;
        }
        System.out.println(sum);
    }
}
